const likes = signal(10);
const label = computed(() => `${likes()} likes`);
label();
likes.set(11);
label();

export class LikeButtonComponent {
  readonly likes = signal(10);
  readonly label = computed(() => `${this.likes()} likes`);

  reset() {
    this.label.set('0 likes');
  }
}

export class FeedComponent {
  readonly posts = signal<Post[]>([]);
  readonly hasPosts = signal(false);
  readonly postCount = computed(() => {
    this.hasPosts.set(this.posts().length > 0);
    return this.posts().length;
  });
}
